    t.del_flag = '0'
     and t.tag_name like concat('%', #{tagName}, '%')
     and t.owner_user_id = #{ownerUserId}
     and t.document_type = #{documentType}
     and t.material_category = #{materialCategory}
     and t.status = #{status}

GROUP BY t.tag_id, t.owner_user_id, t.tag_name, t.tag_key, t.document_type, t.material_category,
         t.create_by, t.create_time, t.update_time, t.remark, t.status
ORDER BY t.create_time DESC

SELECT tag_id
FROM sys_document_tag
WHERE document_id = #{documentId}

select tag_id as tagId, owner_user_id as ownerUserId, tag_name as tagName, tag_key as tagKey
from sys_tag
where owner_user_id = #{userId}
  and tag_name = #{tagName}
  and del_flag = '0'
    limit 1

